+
+    fieldset {
+      margin: 0;
+      padding: 0;
+      border: 0;
+      min-width: 0;
+    }
+
+    legend {
+      margin: 0 0 14px;
+      padding: 0;
+      font-size: 1rem;
+      font-weight: 700;
+    }
+
+    .choice-list {
+      display: grid;
+      gap: 12px;
+    }
+
+    .radio-option {
+      display: flex;
+      align-items: center;
+      gap: 12px;
+      padding: 14px 16px;
+      border: 1px solid rgba(151, 164, 198, 0.14);
+      border-radius: 14px;
+      background: rgba(255, 255, 255, 0.03);
+      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
+      cursor: pointer;
+    }
+
+    .radio-option:hover,
+    .radio-option:focus-within {
+      border-color: rgba(110, 168, 254, 0.75);
+      background: rgba(110, 168, 254, 0.08);
+      transform: translateY(-1px);
+    }
+
+    .radio-option input {
+      width: 18px;
+      height: 18px;
+      accent-color: var(--accent);
+      margin: 0;
+      flex: 0 0 auto;
+    }
+
+    .radio-label {
+      font-weight: 600;
+    }
+
+    .submit-button {
+      border: 0;
+      border-radius: 999px;
+      padding: 14px 18px;
+      font: inherit;
+      font-weight: 700;
+      color: #081120;
+      background: linear-gradient(135deg, var(--accent-strong), var(--accent));
+      cursor: pointer;
+      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
+      box-shadow: 0 14px 30px rgba(110, 168, 254, 0.25);
+    }
+
+    .submit-button:hover,
+    .submit-button:focus-visible {
+      transform: translateY(-1px);
+      filter: brightness(1.03);
+      box-shadow: 0 18px 34px rgba(110, 168, 254, 0.32);
+    }
+
+    .submit-button:focus-visible,
+    .radio-option input:focus-visible {
+      outline: 2px solid var(--accent-strong);
+      outline-offset: 2px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      color: var(--accent-strong);
+      font-weight: 600;
+    }
+  </style>
+</head>
+<body>
+  <div id="app"></div>
+
+  <script>
+    function RadioOption({ name, value, label, required }) {
+      const option = document.createElement("label");
+      option.className = "radio-option";
+
+      const input = document.createElement("input");
+      input.type = "radio";
+      input.name = name;
+      input.value = value;
+      input.required = required;
+
+      const text = document.createElement("span");
+      text.className = "radio-label";
+      text.textContent = label;
+
+      option.append(input, text);
+      return option;
+    }
+
+    function RadioGroupField({ question, name, options }) {
+      const wrapper = document.createElement("div");
+      wrapper.className = "form-field";
+
+      const fieldset = document.createElement("fieldset");
+      const legend = document.createElement("legend");
+      legend.textContent = question;
+
+      const list = document.createElement("div");
+      list.className = "choice-list";
+
+      options.forEach((option, index) => {
+        list.appendChild(
+          RadioOption({
+            name,
+            value: option.value,
+            label: option.label,
+            required: index === 0
+          })
+        );
+      });
+
+      fieldset.append(legend, list);
+      wrapper.appendChild(fieldset);
+      return wrapper;
+    }
+
+    function FormSection() {
+      const section = document.createElement("section");
+      const form = document.createElement("form");
+      const status = document.createElement("p");
+      status.className = "status";
+      status.setAttribute("aria-live", "polite");
+
+      form.appendChild(
+        RadioGroupField({
+          question: "How do you prefer to receive notifications?",
+          name: "notificationPreference",
+          options: [
+            { value: "Email", label: "Email" },
+            { value: "SMS", label: "SMS" },
+            { value: "Push Notifications", label: "Push Notifications" }
+          ]
+        })
+      );
+
+      const submitButton = document.createElement("button");
+      submitButton.type = "submit";
+      submitButton.className = "submit-button";
+      submitButton.textContent = "Submit";
+
+      form.append(submitButton, status);
+
+      form.addEventListener("submit", function (event) {
+        event.preventDefault();
+        const data = new FormData(form);
+        const selected = data.get("notificationPreference");
+        status.textContent = "Saved preference: " + selected;
+      });
+
+      section.appendChild(form);
+      return section;
+    }
+
+    function App() {
+      const shell = document.createElement("main");
+      shell.className = "app-shell";
+
+      const eyebrow = document.createElement("p");
+      eyebrow.className = "eyebrow";
+      eyebrow.textContent = "Preferences";
+
+      const title = document.createElement("h1");
+      title.textContent = "Choose your notification method";
+
+      const intro = document.createElement("p");
+      intro.className = "intro";
+      intro.textContent = "Select one option below to tell us how you would like to receive updates.";
+
+      shell.append(eyebrow, title, intro, FormSection());
+      return shell;
+    }
+
+    document.getElementById("app").appendChild(App());
+  </script>
+</body>
+</html>
*** End Patch
