      --panel: rgba(18, 25, 46, 0.92);
      --panel-border: rgba(151, 164, 198, 0.2);
      --text: #edf2ff;
      --muted: #a7b1cb;
      --accent: #6ea8fe;
      --accent-strong: #8cc7ff;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
